#include "../audio_output.h"
#include <cstdio>
#include <cstdlib>
#include <algorithm>
#include <limits>
using namespace Snatcher;
namespace {unsigned checks;void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"Audio output failure: %s\n",why);std::exit(1);}}bool equal(const NativeAudioOutputState& a,const NativeAudioOutputState& b){return a.version==b.version&&a.rate==b.rate&&a.frames==b.frames&&a.inputQ16[0]==b.inputQ16[0]&&a.inputQ16[1]==b.inputQ16[1]&&a.outputQ16[0]==b.outputQ16[0]&&a.outputQ16[1]==b.outputQ16[1];}}
int main(){std::string error;NativeAudioOutput whole,parts;std::vector<int32_t> source(44100*2);for(unsigned i=0;i<44100;++i){source[i*2]=int32_t(i%113)*70-3200;source[i*2+1]=1900-int32_t(i%73)*53;}
 std::vector<int16_t> expected(source.size()),actual(source.size());check(whole.process(source.data(),expected.data(),44100,error),"complete native master frame domain");unsigned at=0;const unsigned chunks[]={1,735,3,736,41,4096};while(at<44100){unsigned count=chunks[at%6];if(count>44100-at)count=44100-at;check(parts.process(source.data()+at*2,actual.data()+at*2,count,error),"partitioned native output");at+=count;}check(actual==expected&&equal(whole.snapshot(),parts.snapshot()),"output and semantic state independent of callback partition");
 NativeAudioOutput resumed;NativeAudioOutputState saved=whole.snapshot();check(resumed.restore(saved,error),"native coupling semantic restore");check(whole.process(source.data(),expected.data(),44100,error)&&resumed.process(source.data(),actual.data(),44100,error)&&actual==expected,"exact continuation of both channel histories");
 NativeAudioOutput constant;std::vector<int32_t> dc(16384*2);for(unsigned i=0;i<16384;++i){dc[i*2]=1000;dc[i*2+1]=-2000;}std::vector<int16_t> coupled(dc.size());check(constant.process(dc.data(),coupled.data(),16384,error)&&coupled[0]==1000&&coupled[1]==-2000,"no fitted gain or initial signal-dependent centering");check(coupled[coupled.size()-2]==0&&coupled.back()==0,"summed PCM/CD/FM DC decays in common output domain");
 NativeAudioOutput sum,a,b;std::vector<int32_t> left(source.size()),right(source.size()),combined(source.size());for(size_t i=0;i<source.size();++i){left[i]=source[i];right[i]=int32_t(i%29)-14;combined[i]=left[i]+right[i];}std::vector<int16_t> l(source.size()),r(source.size());check(a.process(left.data(),l.data(),44100,error)&&b.process(right.data(),r.data(),44100,error)&&sum.process(combined.data(),actual.data(),44100,error),"fixed source sum rather than component-specific filters");int maxResidual=0;for(size_t i=0;i<actual.size();++i)maxResidual=std::max(maxResidual,std::abs(int(actual[i])-int(l[i])-int(r[i])));check(maxResidual<=1,"unclipped superposition bounded by final integer rounding");
 NativeAudioOutput clipping;const int32_t wide[]={100000,-100000,0,0};int16_t clamped[4];check(clipping.process(wide,clamped,2,error)&&clamped[0]==32767&&clamped[1]==-32768,"wide CE sum saturates only at output conversion");
 NativeAudioOutputState before=resumed.snapshot(),bad=before;bad.version=2;check(!resumed.restore(bad,error)&&equal(before,resumed.snapshot()),"unknown output-state version rejects transactionally");bad=before;bad.rate=48000;check(!resumed.restore(bad,error)&&equal(before,resumed.snapshot()),"different measurement domain rejects without rescaling state");bad=before;bad.inputQ16[1]=std::numeric_limits<int64_t>::min();check(!resumed.restore(bad,error)&&equal(before,resumed.snapshot()),"corrupt wide signed state rejected");bad=before;bad.inputQ16[0]=1;check(!resumed.restore(bad,error)&&equal(before,resumed.snapshot()),"fractional input history cannot originate in the32-bit CE source sum");bad=before;bad.outputQ16[0]=INT64_C(1)<<40;check(!resumed.restore(bad,error)&&equal(before,resumed.snapshot()),"impossible coupling transient bound rejected");const int32_t impossible[]={1048577,0};check(!resumed.process(impossible,clamped,1,error)&&equal(before,resumed.snapshot()),"out-of-domain source sum rejects before altering history");bad=before;bad.frames=std::numeric_limits<uint64_t>::max();check(resumed.restore(bad,error)&&!resumed.process(source.data(),actual.data(),1,error)&&equal(bad,resumed.snapshot()),"sample counter exhaustion preserves live output history");check(!parts.process(nullptr,actual.data(),1,error)&&!parts.process(source.data(),actual.data(),0,error),"invalid output extent rejected");parts.reset();NativeAudioOutput fresh;check(equal(parts.snapshot(),fresh.snapshot()),"new-session barrier removes final output history");
 std::printf("Native audio output: %u checks,0 failures\n",checks);return 0;}
